import{_ as a,o as i,c as e,a2 as l}from"./chunks/framework.BsgK4TUM.js";const p=JSON.parse('{"title":"Multilingual","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/multilingual.md","filePath":"user-guide/multilingual.md"}'),o={name:"user-guide/multilingual.md"};function n(s,t,r,u,d,c){return i(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="multilingual" tabindex="-1">Multilingual <a class="header-anchor" href="#multilingual" aria-label="Permalink to &quot;Multilingual&quot;">​</a></h1><p>When your Concrete CMS site is configured with <a href="/community_store/how-tos/multilingual.html">multiple languages</a>, product details, options and other pieces of text displayed in your store can be translated in full. Translations are managed through the <strong>Store / Multilingual</strong> Dashboard page.</p><p>The translations process is designed such that repeatedly used &#39;common&#39; pieces of text to describe products and product options only needs to be translated once, instead of on each product. Community Store will refer to the &#39;common&#39; translations first when displaying a translated product, but the pieces of text can still be individually translated on a per-product basis if necessary.</p><p>Therefore, it is suggested to visit the <strong>Store / Multilingual / Common</strong> Dashboard page first and complete the translations there, before working through individual product translations.</p><h2 id="product-translations" tabindex="-1">Product Translations <a class="header-anchor" href="#product-translations" aria-label="Permalink to &quot;Product Translations&quot;">​</a></h2><p>The following items can be translated per product in this section:</p><ul><li>Product Name</li><li>Short Description</li><li>Details</li><li>Quantity Label</li><li>Add To Cart Button Label</li><li>Out of Stock Message</li><li>Option Names</li><li>Option Details</li><li>Product Attribute Names and Values</li></ul><h2 id="checkout-translations" tabindex="-1">Checkout Translations <a class="header-anchor" href="#checkout-translations" aria-label="Permalink to &quot;Checkout Translations&quot;">​</a></h2><p>The following site-wide items can be translated in this section:</p><ul><li>Payment Method Display Names</li><li>Payment Method Button Labels</li><li>Shipping Method Names</li><li>Shipping Method Details</li><li>Tax Rate Names</li><li>Discount Display Names</li><li>Order Attribute Names and Values</li><li>Receipt Email Header</li><li>Receipt Email Footer</li></ul><h2 id="common-translations" tabindex="-1">Common Translations <a class="header-anchor" href="#common-translations" aria-label="Permalink to &quot;Common Translations&quot;">​</a></h2><p>The following items can be translated in this section, and act as default translations:</p><ul><li>Option Names</li><li>Option Details</li><li>Product Quantity Labels</li><li>Product Add To Cart Button Labels</li><li>Product Out of Stock Messages</li><li>Product Attribute Names and Values</li></ul>',13)])])}const m=a(o,[["render",n]]);export{p as __pageData,m as default};
